-- Tan Yan Kee Academic Building (TYK): ground floor to 10th floor, rooms, offices, comfort rooms, the library,
-- four stairwells and two elevator banks. The "CFAD building" is its west wing.
-- GENERATED by sql/tools/tan-yan-kee.ps1 from the posted floor plans and the building directory. Edit the script and
-- run it again rather than editing this file. Positions are estimates; the ground floor has no plan yet.
-- Safe to run more than once; keeps the usage log. Run after 05_campus_layout.sql (and again whenever 05 is run).
-- Then copy GET /api/snapshot into uenav-mobile/src/main/resources/campus-snapshot.json before building the APK.

USE uenav;

-- the CFAD building is the west wing of Tan Yan Kee (owner, 2026-11-15): its door joins TYK, building 7 goes
UPDATE node SET building_id = 3, name = 'CFAD Building (Tan Yan Kee west wing)' WHERE node_id = 34;
DELETE FROM building WHERE building_id = 7 AND NOT EXISTS (SELECT 1 FROM node WHERE node.building_id = 7)
  AND NOT EXISTS (SELECT 1 FROM floor WHERE floor.building_id = 7);
UPDATE building SET map_x = 850, map_y = 705, description = 'Ten floors. The CFAD wing is its angled west end. Position from a satellite photo and OpenStreetMap, checked by a student' WHERE building_id = 3;
-- main door under the 2F canopy, on the field side
UPDATE node SET x = 891, y = 661 WHERE node_id = 33;
UPDATE edge SET distance_m = 14 WHERE (from_node_id = 15 AND to_node_id = 33) OR (from_node_id = 33 AND to_node_id = 15);

ON DUPLICATE KEY UPDATE building_id = VALUES(building_id), floor_number = VALUES(floor_number), floor_name = VALUES(floor_name);

-- every walkway inside the building (and its links to the doors) is rebuilt below
DELETE FROM edge WHERE from_node_id IN (SELECT node_id FROM (SELECT node_id FROM node WHERE building_id = 3 AND floor_id IS NOT NULL) b)
                  OR to_node_id IN (SELECT node_id FROM (SELECT node_id FROM node WHERE building_id = 3 AND floor_id IS NOT NULL) b);
